SELECT * FROM customers;
-- total revenue generated by male and female customers
select gender, SUM(purchase_amount) as revenue
from customers group by gender;
-- which customers used a discount on their purchases still spent more than the average purchase amount
select customer_id, purchase_amount
from customers where discount_applied = 'Yes' and purchase_amount > (select AVG(purchase_amount) from customer_behaviour.customers);
-- which are the top products with highest average review ratings
select item_purchased, AVG(review_rating) as avg_rating 
from customers group by item_purchased
order by (avg_rating) desc;
-- average purchase amount for customers who used express shipping vs standard shipping
select shipping_type,
ROUND(AVG(purchase_amount),2) as avg_purchase_amount
from customers
where shipping_type in ('Express', 'Standard')
group by shipping_type;
-- do subscribed customers spend more on average than non-subscribed customers
select subscription_status,
COUNT(customer_id) as total_customers,
ROUND(AVG(purchase_amount),2) as avg_purchase_amount,
ROUND(SUM(purchase_amount),2) as total_revenue
from customers
group by subscription_status
order by total_revenue, avg_purchase_amount desc;
-- which products have the highest percentage of discount applied
select item_purchased,
ROUND(100*SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/ COUNT(*),2) as discount_rate
from customers
group by item_purchased
order by discount_rate desc;
-- segment customers into new, returning, and loyal based on their previous purchases and show the count of each segment
with customer_type as(
select customer_id,previous_purchases,
CASE
WHEN previous_purchases = 1 THEN 'New'
WHEN previous_purchases BETWEEN 1 AND 10 THEN 'Returning'
ELSE 'Loyal' END as customer_segment
from customers)
select customer_segment, COUNT(*) as "Number of Customers"
from customer_type
group by customer_segment;
-- what are the most purchased products within each category
with item_counts as (
select category, item_purchased,
COUNT(customer_id) as total_orders,
ROW_NUMBER() OVER (PARTITION BY category ORDER BY COUNT(customer_id) DESC) as item_rank
from customers
group by category, item_purchased)
select item_rank, category, item_purchased, total_orders
from item_counts
where item_rank <= 3;
-- are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select subscription_status,
COUNT(customer_id) as repeat_buyers
FROM customers 
where previous_purchases > 5
group by subscription_status;
-- what is the revenue contribution of each age group
select age_group,
sum(purchase_amount) as total_revenue
from customers
group by age_group
order by total_revenue desc;





